#include<bits/stdc++.h>
#define int long long
using namespace std;

const int MAX_LIMIT = 5620; 
int gsm[MAX_LIMIT + 5][MAX_LIMIT + 5];

int ksm(int x, int y){
    if(x > MAX_LIMIT || y > MAX_LIMIT) {
        if(y == 0) return 1;
        if(y == 1) return x % LLONG_MAX;
        int ans = ksm(x, y / 2) % LLONG_MAX;
        // 使用 (__int128) 强制转换，防止 ans * ans 阶段溢出
        ans = (int)((__int128)ans * ans % LLONG_MAX);
        if(y % 2) ans = (int)((__int128)ans * x % LLONG_MAX);
        return ans;
    }

    if(gsm[x][y] != 0) return gsm[x][y];
    if(y == 0) return gsm[x][y] = 1;
    if(y == 1) return gsm[x][y] = x % LLONG_MAX;
    
    int ans = ksm(x, y / 2) % LLONG_MAX;
    // 同样使用 (__int128) 保护数组内部的计算
    ans = (int)((__int128)ans * ans % LLONG_MAX);
    if(y % 2) ans = (int)((__int128)ans * x % LLONG_MAX);
    return gsm[x][y] = ans;
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    // 单线程跑 5620 的双重循环已经极快了（0.02秒），完全不需要多线程
    for(int i = 1; i <= MAX_LIMIT; i++) {
        for(int j = 1; j <= MAX_LIMIT; j++) {
            ksm(i, j);
        }
    }

    // 此时大数乘法被 __int128 保护，计算出的值绝对精确
    cout << ksm(3037000499976118, 2) << "\n";

    return 0;
}
